    return focused+comparison+`<details class="career-research-scope"><summary>本轮可读 ${(row.document_ids||[]).length} 份归档材料 · 当时另 ${row.omitted_documents} 份未带入</summary><p class="form-note">这是本轮可查阅的目录，不代表已经读完；JD按本轮目标岗位另行读取。${["role","map"].includes(row.kind)?"岗位理解不带入个人简历、经历和作品。":"优先本次选中的材料、经历、实验及关联来源，再补充近期资料。"}未带入的资料仍留在书架，可以另行选中研究。</p><ul>${(row.document_ids||[]).map(id=>`<li>${exporting?e(names.get(id)||"当时选用的归档材料"):`<button type="button" class="text-button" data-public-source="${e(id)}">${e(names.get(id)||"当时选用的归档材料")} ↗</button>`}</li>`).join("")}</ul></details>`;
