    if(!materials.length&&!draft.material_id)return hidden+'<input type="hidden" name="material_id" value="">';
    return hidden+`<label>本次重点回查的资料（可选）<select name="material_id"><option value="">不指定重点资料，从当前材料出发</option>${draft.material_id&&!selected?`<option value="${e(draft.material_id)}" selected>先前选中的资料已移出，请重新选择</option>`:""}${materials.map(row=>`<option value="${e(row.id)}" ${row.id===draft.material_id?"selected":""}>${e(row.title)}</option>`).join("")}</select></label>${selected?`<div class="result-actions"><button type="button" class="text-button" data-public-source="${e(selected.id)}">核对这份资料原文 ↗</button><button type="button" class="text-button" data-career-clear-material-focus>不限定这份资料</button>${saveMaterialFocusButton(data,draft,[selected.id])}</div>`:""}<p class="form-note">可结合新材料重查已选认识、调查问题或历史分析；切换资料不会清空问题，也不会开始研究。</p>`;
